function faceMarkup(r,s){const index='<text class="sol-rank" x="10" y="19" text-anchor="middle" font-size="'+(r===10?16:18)+'" '+(r===10?'textLength="16" lengthAdjust="spacingAndGlyphs"':'')+'>'+symbols[r]+'</text><path d="'+suitPaths[s]+'" transform="translate(6.64 24) scale(.28)"/>';const marks=r>=11?'':pips[r].map(([x,y])=>{const scale=r===1?1.55:.62,cx=30+x*.4,cy=34+y*.75;return '<path class="sol-pip" d="'+suitPaths[s]+'" transform="translate('+(cx-12*scale)+' '+(cy-12*scale)+') scale('+scale+')"/>';}).join('');return '<svg class="sol-face" viewBox="0 0 100 143" preserveAspectRatio="none" aria-hidden="true"><g class="sol-index">'+index+'</g>'+marks+'<g class="sol-index" transform="translate(100 143) rotate(180)">'+index+'</g></svg>';}
